import pyomo.environ as pyo

DATA = {
    "num_jobs": 7,
    "num_ops": 2,
    "processing_time": 1,
    "big_M": 100000,
}


def build_model(data=None):
    d = data or DATA
    n_jobs = d["num_jobs"]
    n_ops = d["num_ops"]
    p = d["processing_time"]
    big_m = d["big_M"]

    model = pyo.ConcreteModel()

    model.JOBS = pyo.RangeSet(0, n_jobs - 1)
    model.OPS = pyo.RangeSet(0, n_ops - 1)

    # Ordered pairs of distinct operations sharing the machine
    op_pairs = [
        (j, o, k, q)
        for j in range(n_jobs)
        for o in range(n_ops)
        for k in range(n_jobs)
        for q in range(n_ops)
        if (j, o) < (k, q)
    ]
    model.OP_PAIRS = pyo.Set(initialize=op_pairs, dimen=4)

    # Start times of each operation
    model.start = pyo.Var(
        model.JOBS, model.OPS, within=pyo.NonNegativeReals
    )

    # Makespan
    model.makespan = pyo.Var(within=pyo.NonNegativeReals)

    # Binary precedence: 1 if (j,o) precedes (k,q) on the shared machine
    model.precedence = pyo.Var(
        model.OP_PAIRS, within=pyo.Binary
    )

    # Precedence within each job
    def job_precedence_rule(m, j, o):
        if o == 0:
            return pyo.Constraint.Skip
        return m.start[j, o] >= m.start[j, o - 1] + p

    model.job_precedence = pyo.Constraint(
        model.JOBS, model.OPS, rule=job_precedence_rule
    )

    # Disjunctive non-overlap constraints for shared machine
    def nonoverlap_first_rule(m, j, o, k, q):
        return (
            m.start[k, q]
            >= m.start[j, o] + p - big_m * (1 - m.precedence[j, o, k, q])
        )

    model.nonoverlap_first = pyo.Constraint(
        model.OP_PAIRS, rule=nonoverlap_first_rule
    )

    def nonoverlap_second_rule(m, j, o, k, q):
        return (
            m.start[j, o]
            >= m.start[k, q] + p - big_m * m.precedence[j, o, k, q]
        )

    model.nonoverlap_second = pyo.Constraint(
        model.OP_PAIRS, rule=nonoverlap_second_rule
    )

    # Makespan at least completion of every operation
    def makespan_rule(m, j, o):
        return m.makespan >= m.start[j, o] + p

    model.makespan_bound = pyo.Constraint(
        model.JOBS, model.OPS, rule=makespan_rule
    )

    model.obj = pyo.Objective(expr=model.makespan, sense=pyo.minimize)

    return model
